            await apiFetch(`/api/todos/${todo.id}`, { method: "PATCH", body: { title: newTitle } });
            showMessage("Renamed.", "success");
            loadTodos();
          } catch (err) {
            if (err instanceof ApiError) {
              showMessage(err.message, "error");
            } else {
              showMessage("Failed to rename.", "error");
            }
          }
        } else {
          loadTodos();
        }
      };
      input.addEventListener("blur", save);
      input.addEventListener("keydown", (e) => {
        if (e.key === "Enter") save();
        if (e.key === "Escape") loadTodos();
      });
      clear(titleSpan);
      titleSpan.appendChild(input);
      input.focus();
      input.select();
    }

    async function deleteTodo(id) {
      if (!confirm("Delete this todo?")) return;
      try {
        await apiFetch(`/api/todos/${id}`, { method: "DELETE" });
        showMessage("Deleted.", "success");
        loadTodos();
      } catch (err) {
        if (err instanceof ApiError) {
          showMessage(err.message, "error");
        } else {
          showMessage("Failed to delete.", "error");
        }
      }
    }

    addForm.addEventListener("submit", async (e) => {
      e.preventDefault();
      await whileBusy(addForm, async () => {
        const data = formValues(addForm);
        try {
          await apiFetch("/api/todos", { method: "POST", body: data });
          showMessage("Added.", "success");
          addForm.reset();
          loadTodos();
        } catch (err) {
          if (err instanceof ApiError) {
            showMessage(err.message, "error");
          } else {
            showMessage("Failed to add todo.", "error");
          }
        }
      });
    });

    prevBtn.addEventListener("click", () => {
      if (currentPage > 0) {
        currentPage--;
        loadTodos();
      }
    });

    nextBtn.addEventListener("click", () => {
      currentPage++;
      loadTodos();
    });

    for (const radio of filterRadios) {
      radio.addEventListener("change", () => {
        currentFilter = radio.value;
        currentPage = 0;
        loadTodos();
      });
    }

    signoutBtn.addEventListener("click", () => {
      clearToken();
      location.href = "login.html";
    });

    await loadUser();
    await loadTodos();
  </script>
</body>
